/** Webpack asset module declarations for images and video imported in React. */
declare module "*.png" {
  const value: string;
  export default value;
}
declare module "*.jpg" {
  const value: string;
  export default value;
}
declare module "*.jpeg" {
  const value: string;
  export default value;
}
declare module "*.svg" {
  const value: string;
  export default value;
}
declare module "*.mp4" {
  const value: string;
  export default value;
}
declare module "*.webm" {
  const value: string;
  export default value;
}
declare module "*.ogg" {
  const value: string;
  export default value;
}